class SavingsGoal {
    private final String name;
    private final int target;
    private int saved;

    SavingsGoal(String name, int target) {
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("name required");
        }
        if (target <= 0) {
            throw new IllegalArgumentException("target must be positive");
        }
        this.name = name;
        this.target = target;
        this.saved = 0;
    }

    int deposit(int amount) {
        if (amount <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        int added = Math.min(amount, target - saved);
        saved += added;
        return added;
    }

    int remaining() {
        return target - saved;
    }

    boolean isReached() {
        return saved == target;
    }

    String getName() {
        return name;
    }
}

