class OutOfStockException extends Exception {
    private final int missing;

    OutOfStockException(String message, int missing) {
        super(message);
        this.missing = missing;
    }

    int getMissing() {
        return missing;
    }
}

class Shelf {
    private final Map<String, Integer> stock = new HashMap<String, Integer>();

    void add(String item, int qty) {
        stock.put(item, count(item) + qty);
    }

    int count(String item) {
        Integer n = stock.get(item);
        return n == null ? 0 : n;
    }

    void take(String item, int qty) throws OutOfStockException {
        int have = count(item);
        if (have < qty) {
            throw new OutOfStockException(item + " is short", qty - have);
        }
        stock.put(item, have - qty);
    }
}

public class Main {
