package orders;

import java.util.ArrayList;
import java.util.List;

/** The orders waiting for payment. */
public class OrderBook {
    private final List<Order> orders = new ArrayList<Order>();

    public void add(Order order) {
        orders.add(order);
    }

    public int size() {
        return orders.size();
    }

    /** The ids of the orders still in the book, in the order they were added. */
    public List<String> ids() {
        List<String> ids = new ArrayList<String>();
        for (Order order : orders) {
            ids.add(order.getId());
        }
        return ids;
    }

    /** Removes every order that expired at or before now. Returns how many were removed. */
    public int purgeExpired(long now) {
        int removed = 0;
        for (Order order : orders) {
            if (order.isExpired(now)) {
                orders.remove(order);
                removed++;
            }
        }
        return removed;
    }

    /** One line per order for the daily summary email. */
    public List<String> summaryLines() {
        List<String> lines = new ArrayList<String>();
        for (Order order : orders) {
            String email = order.getCustomer().getEmail().toLowerCase();
            lines.add(order.getId() + " " + order.getCustomer().getName() + " <" + email + "> x" + order.getUnits());
        }
        return lines;
    }
}

package orders;

public class Customer {
    private final String name;
    private final String email;     // null for a guest checkout

    public Customer(String name, String email) {
        this.name = name;
        this.email = email;
    }

    public String getName() {
        return name;
    }

    /** The contact address, or null if the customer checked out as a guest. */
    public String getEmail() {
        return email;
    }
}

package orders;

/** Builds a small order book, drops expired orders and prints the daily summary. */
public class Main {
    public static void main(String[] args) {
        long now = 10000L;
        OrderBook book = new OrderBook();
        book.add(new Order("A-100", new Customer("Leon", "Leon@Example.test"), 3, 5000L));    // expired
        book.add(new Order("A-101", new Customer("Mia", "mia@example.test"), 1, 20000L));
        book.add(new Order("A-102", new Customer("Emma", "emma@example.test"), 2, 8000L));    // expired
        book.add(new Order("A-103", new Customer("Guest", null), 5, 30000L));                 // guest checkout
        book.add(new Order("A-104", new Customer("Jack", "jack@example.test"), 4, 40000L));

        int removed = book.purgeExpired(now);
        System.out.println("purged " + removed + " expired orders, " + book.size() + " left");
        for (String line : book.summaryLines()) {
            System.out.println(line);
        }
    }
}
